def rasterize(ch, scale=1, color=None):
    """Repaint a glyph from its rectangle cover (exact RGBA). With
    ``color``, the stored rgb is multiplied (like FontRenderer tint)."""
    surf = pygame.Surface((TILE * scale, TILE * scale), pygame.SRCALPHA)
    for (x, y, w, h, r, g, b, al) in GLYPH_VECTORS.get(ch, ()):
        if color is not None:
            r = r * color[0] // 255
            g = g * color[1] // 255
            b = b * color[2] // 255
        surf.fill((r, g, b, al), (x * scale, y * scale, w * scale, h * scale))
    return surf


def has_glyph(ch):
    return ch in GLYPH_VECTORS


class AtlasFont:
    """Drop-in-ish reference renderer (positions in TILE*scale units)."""

    tile = TILE

    def __init__(self, scale=1):
        self.scale = scale

    def draw_char(self, surface, ch, x, y, color=None, y_px_offset=0):
        if ch == " " or ch not in GLYPH_VECTORS:
            return
        surface.blit(rasterize(ch, self.scale, color),
                     (x * TILE * self.scale, y * TILE * self.scale + y_px_offset))

    def draw_text(self, surface, text, x, y, color=None):
        for i, ch in enumerate(str(text)):
            self.draw_char(surface, ch, x + i, y, color)


def selftest(atlas="alienraid12x12.png", map_path="charset_map.json"):
    """Re-verify the vectors against the PNG: byte-exact or fail."""
    root = os.path.join(os.path.dirname(os.path.abspath(__file__)), os.pardir)
    atlas = atlas if os.path.isfile(atlas) else os.path.join(root, atlas)
    map_path = map_path if os.path.isfile(map_path) else os.path.join(root, map_path)
    if not (os.path.isfile(atlas) and os.path.isfile(map_path)):
        print("selftest skipped: atlas/map not found")
        return 0
    tool = os.path.join(root, "tools", "atlas_to_code.py")
    spec = importlib.util.spec_from_file_location("atlas_to_code", tool)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    cells = mod.load_cells(atlas)
    char_map, _s, _e = mod.load_char_data(map_path)
    bad = 0
    for ch, (col, row) in sorted(char_map.items()):
        if len(ch) != 1:
            continue
        want = pygame.image.tostring(cells[(col, row)], "RGBA")
        got = pygame.image.tostring(rasterize(ch), "RGBA")
        if want != got:
            print("MISMATCH: {0!r}".format(ch))
            bad += 1
    if bad:
        print("{0} glyphs differ from the atlas".format(bad))
        return 1
    print("OK: {0} glyphs round-trip pixel-exact".format(
        sum(1 for c in char_map if len(c) == 1)))
    return 0


if __name__ == "__main__":
    raise SystemExit(selftest())
